/**
 * Photo pipeline against the Firestore emulator (`npm run test:emulator`). Vercel Blob is replaced by an
 * in-memory fake, so nothing is uploaded anywhere. Images are generated by the test.
 */
import { test, before } from "node:test";
import assert from "node:assert/strict";
import sharp from "sharp";

const PROJECT = "demo-italianshoes";
assert.ok(process.env.FIRESTORE_EMULATOR_HOST, "run via `npm run test:emulator`");
process.env.GCLOUD_PROJECT ??= PROJECT;

const { db } = await import("../../functions/lib/admin.js");
const images = await import("../../functions/services/images.js");
const catalog = await import("../../functions/services/catalog.js");
const products = await import("../../functions/services/products.js");
const schemas = await import("../../functions/shared/schemas/index.js");

const STAFF = "staff-1";
const HOST = "https://abc123.public.blob.vercel-storage.com";
const ids = {};

/** In-memory Blob: url → Buffer. */
const store = new Map();
const deleted = [];
images.blobIO.fetchSource = async (url) => {
  if (!store.has(url)) throw new Error("missing");
  return store.get(url);
};
images.blobIO.put = async (pathname, body) => {
  const url = `${HOST}/${pathname}`;
  store.set(url, body);
  return url;
};
images.blobIO.del = async (urls) => {
  for (const u of [urls].flat()) {
    deleted.push(u);
    store.delete(u);
  }
};
const original = (name, buffer) => {
  const url = `${HOST}/uploads/${ids.p}/${name}`;
  store.set(url, buffer);
  return url;
};
const jpeg = (w = 900, h = 700, exif = false) => {
  const img = sharp({ create: { width: w, height: h, channels: 3, background: "#7a5c3e" } });
  return (exif ? img.withExif({ IFD0: { Copyright: "secret-camera-owner" } }) : img).jpeg().toBuffer();
};

before(async () => {
  await fetch(`http://${process.env.FIRESTORE_EMULATOR_HOST}/emulator/v1/projects/${PROJECT}/databases/(default)/documents`, { method: "DELETE" });
  const cat = (await catalog.saveCatalogItem("category", schemas.saveCategoryInput.parse({ name: "Formal", slug: "formal" }), STAFF)).id;
  ids.p = (await products.saveProduct(schemas.saveProductInput.parse({ name: "Photo Test", slug: "photo-test", categoryId: cat, sku: "PH-1" }), STAFF)).id;
});

test("a real photo becomes three WebP sizes, metadata stripped, original deleted, first photo is the main one", async () => {
  const src = original("a1", await jpeg(2000, 1500, true));
  const { imageId } = await images.addProductImage({ productId: ids.p, url: src }, STAFF);
  const img = (await db.doc(`products/${ids.p}`).get()).data().images[0];
  assert.deepEqual([img.id, img.isPrimary, Object.keys(img.paths)], [imageId, true, ["400", "800", "1600"]]);
  for (const w of [400, 800, 1600]) {
    assert.match(img.paths[w], /^https:\/\/abc123\.public\.blob\.vercel-storage\.com\/products\//);
    const meta = await sharp(store.get(img.paths[w])).metadata();
    assert.equal(meta.format, "webp");
    assert.equal(meta.width, w);
    assert.equal(meta.exif, undefined, "camera/location data is removed");
  }
  assert.ok(deleted.includes(src) && !store.has(src), "the original is deleted");
  assert.ok((await db.collection("auditLogs").where("action", "==", "product.image_added").get()).size >= 1);

  const second = original("a2", await jpeg());
  await images.addProductImage({ productId: ids.p, url: second }, STAFF);
  const list = (await db.doc(`products/${ids.p}`).get()).data().images;
  assert.deepEqual(list.map((i) => i.isPrimary), [true, false]);
});

test("fake, tiny, or non-image files are rejected with a clear reason, and the original is removed", async () => {
  const cases = [
    [Buffer.from("<svg xmlns='http://www.w3.org/2000/svg'><script>alert(1)</script></svg>"), /isn't a valid image|Use a JPEG/],
    [Buffer.from("just text pretending to be a photo.jpg"), /isn't a valid image/],
    [await jpeg(100, 100), /too small/],
    [await sharp({ create: { width: 600, height: 600, channels: 3, background: "#fff" } }).gif().toBuffer(), /Use a JPEG, PNG or WebP/],
  ];
  const before = (await db.doc(`products/${ids.p}`).get()).data().images.length;
  let n = 0;
  for (const [buffer, reason] of cases) {
    const url = original(`bad${(n += 1)}`, buffer);
    await assert.rejects(images.addProductImage({ productId: ids.p, url }, STAFF), (e) => e.code === "invalid-argument" && reason.test(e.message));
    assert.ok(!store.has(url), "rejected originals are deleted");
  }
  assert.equal((await db.doc(`products/${ids.p}`).get()).data().images.length, before, "nothing was added");
  await assert.rejects(images.processImageBuffer(Buffer.alloc(8 * 1024 * 1024 + 1)), /larger than 8 MB/);
});

test("only uploads from our own Blob store, inside this product's folder, are fetched", async () => {
  const bad = [
    "https://evil.example.com/uploads/" + ids.p + "/x",
    "http://abc123.public.blob.vercel-storage.com/uploads/" + ids.p + "/x",
    `${HOST}/uploads/another-product/x`,
    `${HOST}/products/${ids.p}/images/x-400.webp`,
    "http://169.254.169.254/latest/meta-data",
    "not a url",
  ];
  for (const url of bad) await assert.rejects(images.addProductImage({ productId: ids.p, url }, STAFF), (e) => e.code === "invalid-argument", url);
  await assert.rejects(images.addProductImage({ productId: "nope", url: `${HOST}/uploads/nope/x` }, STAFF), (e) => e.code === "not-found");
});

test("photo actions: main photo, order, alt text, and deleting removes the files; a published product keeps one", async () => {
  const [a, b] = (await db.doc(`products/${ids.p}`).get()).data().images;
  await images.imageAction({ productId: ids.p, action: "primary", imageId: b.id }, STAFF);
  await images.imageAction({ productId: ids.p, action: "alt", imageId: b.id, alt: "Side view" }, STAFF);
  await images.imageAction({ productId: ids.p, action: "reorder", order: [b.id, a.id] }, STAFF);
  let list = (await db.doc(`products/${ids.p}`).get()).data().images;
  assert.deepEqual(list.map((i) => [i.id, i.isPrimary, i.alt]), [[b.id, true, "Side view"], [a.id, false, ""]]);
  await assert.rejects(images.imageAction({ productId: ids.p, action: "reorder", order: [b.id] }, STAFF), (e) => e.code === "invalid-argument");

  deleted.length = 0;
  await images.imageAction({ productId: ids.p, action: "delete", imageId: b.id }, STAFF);
  assert.deepEqual(deleted.sort(), Object.values(b.paths).sort(), "all three files were deleted");
  list = (await db.doc(`products/${ids.p}`).get()).data().images;
  assert.deepEqual(list.map((i) => [i.id, i.isPrimary]), [[a.id, true]], "the next photo becomes the main one");

  await db.doc(`products/${ids.p}`).update({ status: "published" });
  await assert.rejects(images.imageAction({ productId: ids.p, action: "delete", imageId: a.id }, STAFF), (e) => /at least one photo/.test(e.message));
});

test("upload tokens: only signed-in staff with products.write, only for an uploads/ path, images only, 8 MB", async () => {
  const claims = {
    writer: { uid: "w1", staff: true, perms: ["products.write"], auth_time: 9999999999 },
    other: { uid: "i1", staff: true, perms: ["inventory.adjust"], auth_time: 9999999999 },
    shopper: { uid: "s1" },
  };
  const verifyToken = async (t) => {
    if (!(t in claims)) throw new Error("forged");
    return claims[t];
  };
  const ask = (pathname, authorization) => images.authorizeBlobUpload({ pathname, authorization }, { verifyToken });
  // Staff sessions are checked against Auth live; for the fake claims we only test the paths that stop before that.
  await assert.rejects(ask(`uploads/${ids.p}/a`), (e) => e.code === "unauthenticated");
  await assert.rejects(ask(`uploads/${ids.p}/a`, "Bearer forged"), (e) => e.code === "unauthenticated");
  await assert.rejects(ask(`uploads/${ids.p}/a`, "Bearer shopper"), (e) => e.code === "permission-denied");
  await assert.rejects(ask(`uploads/${ids.p}/a`, "Bearer other"), (e) => e.code === "permission-denied");
  assert.deepEqual(images.IMAGE_WIDTHS, [400, 800, 1600]);
});
